def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # Horizontal solid rows form boundaries around a band; a distinct cell
    # on the boundary indicates the column to color within that band.
    solid = []
    for r, row in enumerate(out):
        counts = {}
        for v in row:
            counts[v] = counts.get(v, 0) + 1
        color, count = max(counts.items(), key=lambda x: x[1])
        if count >= w - 1:
            solid.append((r, color))

    for i in range(len(solid) - 1):
        top, top_color = solid[i]
        bottom, bottom_color = solid[i + 1]
        if bottom <= top + 1:
            continue

        # A one-cell deviation in the upper boundary signals a column.
        deviations = [c for c, v in enumerate(out[top]) if v != top_color]
        if len(deviations) == 1:
            c = deviations[0]
            for r in range(top + 1, bottom):
                out[r][c] = 1
            break

        # Otherwise extend the band contents to the right edge, coloring
        # the trailing empty portion on rows with an internal pattern.
        for r in range(top + 1, bottom):
            row = out[r]
            vals = [c for c, v in enumerate(row) if v != top_color]
            if vals and any(row[c] == top_color for c in range(vals[-1] + 1, w)):
                last = vals[-1]
                if last > 0 and any(row[c] == top_color for c in range(last)):
                    for c in range(last + 1, w):
                        row[c] = 1
    return out
