def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])

    # A nearly solid horizontal object has a one-cell gap at its end;
    # mark that gap as the extension color.
    for r, row in enumerate(out):
        counts = {}
        for v in row:
            counts[v] = counts.get(v, 0) + 1
        color, count = max(counts.items(), key=lambda item: item[1])
        if count == w - 1:
            for c, v in enumerate(row):
                if v != color:
                    out[r][c] = 1
                    return out

    # In a patterned band, color the empty region to the right of the
    # foreground shape on rows where that shape reaches its right edge.
    bg = max(set(v for row in out for v in row), key=lambda v: sum(row.count(v) for row in out))
    for r, row in enumerate(out):
        cells = [c for c, v in enumerate(row) if v != bg]
        if cells:
            right = max(cells)
            if right < w - 1:
                for c in range(right + 1, w):
                    out[r][c] = 1
    return out
